import type { PracticeExam } from './lccaExams';

export const lccaGroExamsA: PracticeExam[] = [
  {
    id: 'exam-1',
    number: 1,
    title: 'Practice Exam 1',
    description: 'A foundational set of 25 questions on core General Residential Operation rules from Texas 26 TAC Chapter 748, covering permits and notifications, personnel, training, service planning, child rights, safety, and daily care.',
    questions: [
      { id: 'e1q1', domain: 'Regulatory Framework', question: 'Under Chapter 748, a general residential operation (GRO) is a residential child-care operation that provides child care for how many children or young adults?', options: ['Four or more', 'Seven or more', 'Ten or more', 'Thirteen or more'], correct: 1, explanation: 'Under §748.43(29), a general residential operation is a residential child-care operation that provides child care for seven or more children or young adults. The care may include treatment services or programmatic services, and the term covers residential treatment centers and formerly titled emergency shelters, basic child-care operations, and halfway houses.' },
      { id: 'e1q2', domain: 'Regulatory Framework', question: 'As part of the application process, a GRO\'s fiscal plan must include documentation of reserve funds or available credit at least equal to the operation\'s operating costs for the first:', options: ['Three months', 'Six months', 'Nine months', 'Twelve months'], correct: 0, explanation: 'Under §748.101(2), the fiscal plan must include a detailed estimate of operating costs for the first three months, documentation of reserve funds or available credit at least equal to those three months of costs (§748.101(2)(B)), an estimated 12-month budget of income and expenses, and predictable funds sufficient for the first year of operation.' },
      { id: 'e1q3', domain: 'Regulatory Framework', question: 'A new individual becomes a controlling person at your GRO. When must you give written notice to your Licensing Representative?', options: ['As soon as possible, but at least 30 days before the change', 'As soon as possible, but at least 15 days before the change', 'Within 24 hours after the change', 'As soon as possible, but no later than two days after the change'], correct: 3, explanation: 'Under §748.153(3)(B), you must notify your Licensing Representative in writing as soon as possible, but no later than two days after, a new individual becomes a controlling person. The same two-day timeframe applies when a controlling person ceases to be one, when information about a controlling person changes significantly, and when the administrator changes. The 30-day notice (§748.153(1)) is for legal structure, relocation, and operating hours; the 15-day notice (§748.153(2)) is for policy, floor plan, and pool construction changes.' },
      { id: 'e1q4', domain: 'Regulatory Framework', question: 'A GRO operates several cottage homes plus a main office. Under §748.191, where must the operation\'s permit be posted?', options: ['In every cottage home, but not at the main office', 'At the main office; posting in each cottage is not required', 'In a locked file at the main office, available on request', 'Only in the cottage home where the administrator is based'], correct: 1, explanation: 'Under §748.191(1), the permit must be posted in a prominent and publicly accessible place where employees, children, parents, and others can easily see it at all times. An operation does not have to post its permit in its cottage homes as long as it is posted at the main office location. The Keeping Children Safe notice and the emergency evacuation and relocation plans (in each building and living quarters used by children) must also be posted.' },
      { id: 'e1q5', domain: 'Regulatory Framework', question: 'A child tells a caregiver that she sometimes thinks about ending her life, but she has taken no action. Under §748.305, how is this treated?', options: ['It is not reportable as a suicide attempt, since thoughts alone are not an attempt', 'It must be reported to Licensing as a suicide attempt within 24 hours of the statement', 'It must be reported to Licensing and law enforcement immediately after the statement', 'It is reportable only if the child is hospitalized after making the statement'], correct: 0, explanation: 'Under §748.305, a suicide attempt is an act a child commits intending to cause his or her death, using means or methods for causing death; it excludes suicidal gestures where it is clear the act was unlikely to cause death. The rule states that suicidal thoughts are not reportable as a suicide attempt. An actual attempt is a serious incident reportable under §748.303(a)(12). The operation must still respond to the child under its suicide prevention policy required by §748.124.' },
      { id: 'e1q6', domain: 'Administrator & Personnel', question: 'A GRO provides treatment services to 28 children. Under §748.601, which statement is correct?', options: ['The operation must have a treatment director who is a full-time employee', 'The operation may use a part-time treatment director on contract', 'A treatment director is required only if a child has an intellectual disability', 'A treatment director is not required until more than 40 children receive treatment'], correct: 0, explanation: 'Under §748.601, you must have a treatment director if you provide treatment services to 25 or more children, or to more than 30% of the children in your care, and the treatment director must be a full-time employee of the operation. With 28 children receiving treatment services, the 25-child threshold is met.' },
      { id: 'e1q7', domain: 'Administrator & Personnel', question: 'Before hiring an applicant, a GRO must complete the applicant\'s reference checks by contacting at least how many individuals who are unrelated to the applicant?', options: ['One', 'Two', 'Three', 'Four'], correct: 1, explanation: 'Under §748.753(a), before hiring an applicant the operation must complete reference checks by contacting at least two individuals unrelated to the applicant who can provide information about the applicant\'s suitability to work with or around children. Under §748.753(b), if the applicant has a work history of providing care or services to children, at least one of the checks must be with a current or former employer who supervised or knows the applicant\'s job performance in that role.' },
      { id: 'e1q8', domain: 'Administrator & Personnel', question: 'Under §748.511, who may NOT be in possession of a handgun while at the operation or while caring for children?', options: ['Employees only', 'Employees and volunteers, but not contract service providers', 'Only caregivers who are counted in the child/caregiver ratio', 'Employees, contract service providers, and volunteers'], correct: 3, explanation: 'Under §748.511, an employee, contract service provider, or volunteer may not be in possession of a handgun while at the operation or while caring for children. The technical assistance explains the intent is to keep handguns off their persons and off the grounds, including parked vehicles and vehicles used to transport children.' },
      { id: 'e1q9', domain: 'Administrator & Personnel', question: 'A child in your GRO is an immediate danger to self or others and needs constant supervision during sleeping hours. Under §748.1013, the caregiver supervising this child must:', options: ['Check on the child at least every 15 minutes', 'Be awake only while the child is out of bed', 'Be awake at all times while caring for the child', 'Sleep in the child\'s room so a noise will wake the caregiver'], correct: 2, explanation: 'Under §748.1013(a), a caregiver must always be awake when caring for a child needing constant supervision during sleeping hours, such as a medically fragile child or a child who is an immediate danger to self or others. Under §748.1013(b), the caregiver may move the child to a location where the caregiver can directly and continuously supervise, as long as the child has comfortable sleeping arrangements.' },
      { id: 'e1q10', domain: 'Training', question: 'A GRO serves only children who are 12 to 17 years old. Under §748.911(b), at least one caregiver counted in the child/caregiver ratio must hold a current certificate in:', options: ['Pediatric CPR', 'Both pediatric and adult CPR from two different trainers', 'Adult CPR', 'First aid with rescue breathing and choking only'], correct: 2, explanation: 'Under §748.911(b)(2), at least one caregiver counted in the ratio must have a current certificate in adult CPR if the operation serves only children 12 years of age and older. Pediatric CPR is required if the operation serves only children under 12 (§748.911(b)(1)), and both types are needed if the operation serves children from birth through 17 (§748.911(b)(3)). Every caregiver also needs first-aid certification under §748.911(a).' },
      { id: 'e1q11', domain: 'Training', question: 'As part of the required annual training hours, a caregiver at a GRO must complete how many hours of trauma informed care training each year?', options: ['1 hour', '2 hours', '3 hours', '4 hours'], correct: 1, explanation: 'Under §748.930(b)(2), a caregiver\'s required annual training must include 2 hours of trauma informed care. The same subsection requires 1 hour of normalcy and 2 hours of transportation safety if the caregiver transports a child younger than 9. Remaining hours must be in areas appropriate to the needs of the children served (§748.930(d)).' },
      { id: 'e1q12', domain: 'Training', question: 'At a GRO where 30% or more of the children in care receive treatment services, how many hours of supervised child-care experience must a caregiver have before being the only caregiver responsible for a group?', options: ['10 hours', '20 hours', '40 hours', '80 hours'], correct: 2, explanation: 'Under §748.861(b), if 25 or more children, or 30% or more of the total population, receive treatment services, a caregiver must have 40 hours of supervised child-care experience in your operation and/or another operation providing the same treatment services. Until then the caregiver may not be the only caregiver for a group and must be supervised at all times by a caregiver who has met the requirement. The experience must be documented in the personnel record.' },
      { id: 'e1q13', domain: 'Service Planning & Treatment', question: 'Who must develop, sign, and date the preliminary service plan for a child receiving treatment services?', options: ['The treatment director or a professional level service provider', 'The caregiver on duty at the time the child is admitted', 'The child-care administrator, working alone', 'The child\'s parent or the placing agency\'s caseworker'], correct: 0, explanation: 'Under §748.1333, the treatment director or a professional level service provider must develop, sign, and date the preliminary service plan for children receiving treatment services. The plan must be completed within 72 hours of admission (§748.1331(a)).' },
      { id: 'e1q14', domain: 'Service Planning & Treatment', question: 'A GRO plans to admit a child for treatment services for an emotional disorder. The child is NOT coming from another regulated residential child-care operation. The psychiatric evaluation, psychological evaluation, or psychosocial assessment must have been completed within what period before admission?', options: ['30 days', '3 months', 'Six months', '14 months'], correct: 2, explanation: 'Under §748.1219(1)(B), the evaluation or assessment must have been completed within six months of the date of admission if the child is not coming from another regulated residential child-care operation, or within 14 months if the child is coming from one. It must be written, dated, and signed, and include the child\'s diagnosis if it is an evaluation (§748.1219(1)(A)).' },
      { id: 'e1q15', domain: 'Service Planning & Treatment', question: 'By when must you give caregivers responsible for a newly admitted child information about the child\'s immediate needs, such as school enrollment, needed medical care, or clothing?', options: ['Within 7 days of admission', 'Within 72 hours of admission', 'Before the initial service plan is completed', 'By the day you admit the child'], correct: 3, explanation: 'Under §748.1213(a), by the day you admit the child you must give the caregivers responsible for the child information about the child\'s immediate needs. Under §748.1213(b), you must also inform appropriate caregivers of any special needs, such as medical, dietary, or supervision needs, and document that you shared the information.' },
      { id: 'e1q16', domain: 'Service Planning & Treatment', question: 'Whom must you involve in planning a child\'s non-emergency discharge or transfer?', options: ['The administrator and the child\'s parent, who must both sign the plan', 'At least one current caregiver and one professional level service provider', 'The treatment director, a physician, and the placing agency\'s attorney', 'The Licensing Representative and the child\'s assigned caseworker'], correct: 1, explanation: 'Under §748.1433(a), you must involve at least one of the child\'s current caregivers and at least one professional level service provider involved in the child\'s service planning. Under §748.1433(b), you must also invite the child, the parent(s), and any other pertinent person, if appropriate. If you cannot plan with these persons, you must document the reason in the child\'s record (§748.1433(c)).' },
      { id: 'e1q17', domain: 'Child Rights & Discipline', question: 'Within how many days after admission must you review a child\'s rights with the child and the child\'s parent and give each a written copy?', options: ['Three days', 'Five days', 'Seven days', 'Ten days'], correct: 2, explanation: 'Under §748.1103(a), within seven days after you admit a child you must review the child\'s rights with the child and the child\'s parent (unless the parent\'s consent is not required) and give each a written copy. Rights must be written in simple, non-technical terms (§748.1103(b)), and the person informed must sign a statement that he or she has read and understands them (§748.1103(d)).' },
      { id: 'e1q18', domain: 'Child Rights & Discipline', question: 'Under §748.2301(a), who may discipline a child in a GRO?', options: ['Only a caregiver known to and knowledgeable of the child', 'Any employee on duty when the behavior occurs', 'Any volunteer assigned to the child\'s living unit', 'Another child in care whom the caregiver appoints'], correct: 0, explanation: 'Under §748.2301(a), only a caregiver known to and knowledgeable of a child may discipline the child. Each measure must be consistent with policies, not physically or emotionally damaging, individualized, age- and developmentally appropriate, and appropriate to the incident (§748.2301(b)). Under §748.2311, a person in care may never discipline or punish another person in care.' },
      { id: 'e1q19', domain: 'Child Rights & Discipline', question: 'A short personal restraint is defined as a personal restraint that does not last longer than:', options: ['30 seconds', '45 seconds', 'One minute', 'Two minutes'], correct: 2, explanation: 'Under §748.43(67), a short personal restraint is a personal restraint that does not last longer than one minute before the child is released, and §748.2801 sets the same one-minute maximum. Unlike other emergency behavior interventions, a short personal restraint does not require a written order (§748.2501) and may be used by a caregiver who is not qualified in emergency behavior intervention (§748.2453).' },
      { id: 'e1q20', domain: 'Health, Safety & Emergency', question: 'After the inspection required before an initial permit is issued, a GRO must be inspected for gas leaks at least once every:', options: ['6 months', '12 months', '18 months', '24 months'], correct: 3, explanation: 'Under §748.3061, a GRO must be inspected for gas leaks before the initial permit is issued and at least once every 24 months from the date of the last inspection. For natural gas, a licensed plumber or gas company official must conduct the inspection (§748.3063(a)), and the most recent report must be kept at the operation (§748.3065(b)).' },
      { id: 'e1q21', domain: 'Health, Safety & Emergency', question: 'Who must test battery-operated smoke detectors at a GRO, and how often?', options: ['A state or local fire inspector, once each year', 'The administrator or designee, monthly, with documentation', 'Any caregiver on duty, once each week', 'A company licensed by the State Fire Marshal, every quarter'], correct: 1, explanation: 'Under §748.3111(a), the administrator or designee must test all battery-operated smoke detectors monthly by pressing the test button, and the date of the test and the name of the employee who tested must be documented and kept at the operation. An electronic smoke alarm system, by contrast, must be tested at least annually by a company licensed by the State Fire Marshal or by the state or local fire inspector (§748.3111(b)).' },
      { id: 'e1q22', domain: 'Health, Safety & Emergency', question: 'What consent must a GRO obtain to administer routine, preventive, and emergency medications to a child?', options: ['A general written consent', 'A new written consent before each dose', 'Verbal consent from the parent, documented by the caregiver', 'None, if a health-care professional is on site'], correct: 0, explanation: 'Under §748.2001(a), you must obtain a general written consent to administer routine, preventive, and emergency medications. Under §748.2001(b), before administering a new psychotropic medication you must also obtain a written, signed, and dated consent specific to that medication from the person legally authorized to give medical consent.' },
      { id: 'e1q23', domain: 'Health, Safety & Emergency', question: 'May a child in care ever sleep in the same bed with an adult caregiver?', options: ['Yes, with the parent\'s written permission on file', 'Yes, if the service planning team approves it in the service plan', 'Yes, but only during travel and camping situations', 'No; a child may never share a bed with an adult caregiver'], correct: 3, explanation: 'Under §748.3361(c), a child must not sleep in the same bed with an adult caregiver at any time. The travel and camping exception in §748.3361(d) applies only to subsections (a) and (b), which deal with sharing a bedroom, not to the same-bed prohibition.' },
      { id: 'e1q24', domain: 'Daily Care & Program Operations', question: 'A school-age child must be offered three meals and at least one snack each day. What is the maximum time that may pass between the last meal or snack of the day and the first meal of the next day?', options: ['8 hours', '10 hours', '12 hours', '14 hours'], correct: 3, explanation: 'Under §748.1691(b), for a school-age child you must provide three meals and at least one snack a day, and no more than 14 hours may pass between the last meal or snack of the day and the serving of the first meal of the following day.' },
      { id: 'e1q25', domain: 'Daily Care & Program Operations', question: 'A child refuses to come to the dining room for a scheduled meal. Under §748.1699, you:', options: ['Must offer the meal or snack but may not force the child to eat', 'May require the child to eat before joining any activities', 'Must prepare a separate meal of the child\'s choice', 'May withhold the child\'s next meal as a consequence'], correct: 0, explanation: 'Under §748.1699(a), you must offer a meal or snack according to the nutrition rules, but you may not force the child to eat, and you are not required to offer other food to a child who refuses a meal or chooses not to be present. Recurring eating problems must be discussed with the parent (§748.1699(b)). Withholding food that meets nutritional requirements as punishment is prohibited by §748.2307(14).' },
    ],
  },
  {
    id: 'exam-2',
    number: 2,
    title: 'Practice Exam 2',
    description: 'A second foundational set of 25 questions on Texas 26 TAC Chapter 748 for general residential operations, with more detailed rules on notifications, serious-incident timeframes, qualifications, emergency behavior intervention, and safety inspections.',
    questions: [
      { id: 'e2q1', domain: 'Regulatory Framework', question: 'Your GRO plans to begin construction to add a swimming pool. Under §748.153(2)(C), when must you give written notification to your Licensing Representative?', options: ['Within two days after construction begins', 'As soon as possible, but at least 15 days before construction begins', 'As soon as possible, but at least 30 days before construction begins', 'Within 24 hours after the pool is completed'], correct: 1, explanation: 'Under §748.153(2)(C), you must notify your Licensing Representative in writing as soon as possible, but at least 15 days before construction begins on adding a swimming pool or other permanent body of water. The same 15-day notice applies to changes to policies required by §748.103(b) and changes to the floor plan. A 30-day notice applies to a change in legal structure, relocation, or operating hours (§748.153(1)).' },
      { id: 'e2q2', domain: 'Regulatory Framework', question: 'A child in your GRO is issued a ticket at school by law enforcement, and the citation does not result in the child being detained. What does §748.303(a)(7) require?', options: ['Report to Licensing within two hours and to law enforcement immediately', 'Report to Licensing and the child\'s parent, each within 24 hours', 'Document the ticket in the child\'s record; no outside notification is required', 'Notify the parent within 24 hours of becoming aware; Licensing is not notified'], correct: 3, explanation: 'Under §748.303(a)(7), when a child is issued a ticket at school by law enforcement, or any other citation that does not result in the child being detained, the GRO must notify the parent as soon as possible, but no later than 24 hours after becoming aware of it. A report to Licensing is not required, and law enforcement is not notified. This differs from an arrest or charge under §748.303(a)(6), which is reported to Licensing within 24 hours.' },
      { id: 'e2q3', domain: 'Regulatory Framework', question: 'A 9-year-old child is missing and is still missing after the GRO determines the child is not on the premises. Under §748.303(a)(9), when must the GRO report the absence to law enforcement?', options: ['Immediately, as for a child under six', 'No later than six hours after the absence is discovered', 'Within two hours of determining the child is not on the premises', 'Within 24 hours after becoming aware of the absence'], correct: 2, explanation: 'Under §748.303(a)(9), for the unauthorized absence of a child developmentally or chronologically 6 to 12 years old, if the child is still missing the GRO must report to law enforcement and to the parent within two hours of determining the child is not on the premises, and to Licensing within two hours of notifying law enforcement. Immediate reporting to law enforcement applies to children under six (§748.303(a)(8)); the six-hour timeframe applies to children 13 and older (§748.303(a)(10)).' },
      { id: 'e2q4', domain: 'Regulatory Framework', question: 'You learn of an allegation that a volunteer who has access to children in your GRO abused drugs within the past seven days. Under §748.303(e)(5), whom must you notify?', options: ['Licensing within 24 hours of learning of the allegation; parents are not notified', 'Licensing and the parents of each child, each within 24 hours of the allegation', 'Licensing immediately and law enforcement within one hour of the allegation', 'Licensing only after a drug test or investigation confirms the allegation'], correct: 0, explanation: 'Under §748.303(e)(5), an allegation that a person under the auspices of the GRO who directly cares for or has access to a child has abused drugs within the past seven days must be reported to Licensing within 24 hours after learning of the allegation. The table does not require notice to parents for this type of incident. Reports are made through the Texas Abuse and Neglect Hotline (§748.309) and documented under §748.311.' },
      { id: 'e2q5', domain: 'Administrator & Personnel', question: 'A GRO provides only child-care services (no qualifying treatment population). Which combination meets the minimum qualifications of a professional level service provider under §748.563(c)?', options: ['An associate degree and three years of documented work experience with children in any setting', 'A high school diploma and five years of documented child-care experience in a residential setting', 'A bachelor\'s degree and six months of experience as a volunteer in a residential child-care operation', 'A bachelor\'s degree plus two years of documented full-time experience in residential child care'], correct: 3, explanation: 'Under §748.563(c), to provide services for children other than those described in subsections (a) and (b), a professional level service provider needs either Option 1 (a master\'s degree, or a bachelor\'s degree in social work or another human services field, plus one year of documented full-time experience in residential child care or a related field) or Option 2 (a bachelor\'s degree plus two years of documented full-time experience in residential child care or a related field of child and family services).' },
      { id: 'e2q6', domain: 'Administrator & Personnel', question: 'Under §748.537, the employee designated to handle emergencies in your GRO:', options: ['Must be on call and accessible to caregivers, but need not hold an administrator license', 'Must be a Licensed Child-Care Administrator who is on call every shift', 'Must live in the children\'s living quarters during all overnight hours', 'Must be the treatment director or a designated professional level service provider'], correct: 0, explanation: 'Under §748.537(a)-(c), the person designated to handle emergencies must be on call and accessible to your caregivers, you must inform all caregivers and Licensing of the system and how to contact the person on call, and the employee is not required to be a Licensed Child-Care Administrator. The administrator\'s responsibility to have such a system in place comes from §748.535(3)(C).' },
      { id: 'e2q7', domain: 'Administrator & Personnel', question: 'Before a child in care leaves for an approved unsupervised childhood activity, which action is required of the caregiver under §748.685(d)?', options: ['Obtain the parent\'s written permission before each separate activity', 'Arrange for an employee to follow the child to and from the activity', 'Give the child a return time and a way to reach the caregiver in an emergency', 'Complete a new service plan review before the child leaves'], correct: 2, explanation: 'Under §748.685(d), for an unsupervised childhood activity the caregiver must know where the child will be, give the child a specific time to return to the operation or the caregiver\'s location, provide, arrange, or confirm appropriate transportation, give the child a way to contact the caregiver in an emergency, and be available to respond if the child needs immediate assistance. Under §748.707(c), the service plan may not require prior parental approval for a designated person to consent to such activities.' },
      { id: 'e2q8', domain: 'Administrator & Personnel', question: 'A caregiver\'s group has 10 children. Three of them are away at approved unsupervised childhood activities. For child/caregiver ratio purposes, those three children:', options: ['Still count, because they remain children in care', 'Count as half a child each while they are away', 'Count only if they are under 13 years old', 'Do not count while at the approved activity'], correct: 3, explanation: 'Under §748.1003(d), a child does not count in the child/caregiver ratio while participating in an approved unsupervised childhood activity. Only the seven children remaining with the caregiver count toward the ratio for the group.' },
      { id: 'e2q9', domain: 'Training', question: 'A child-care administrator who holds a relevant professional license must complete how many annual training hours under §748.931?', options: ['10 hours', '15 hours', '20 hours', '25 hours'], correct: 1, explanation: 'Under §748.931(a)(2), child-care administrators, professional level service providers, treatment directors, and case managers who hold a relevant professional license must complete 15 annual training hours; those who do not hold a relevant license must complete 20 hours (§748.931(a)(1)). There are no annual emergency behavior intervention training hours for these employees, but they must be retrained when there is a substantial change in techniques, types of interventions, or policies (§748.931(e)).' },
      { id: 'e2q10', domain: 'Training', question: 'A caregiver completes more than the minimum number of annual training hours in one year. What is the maximum number of those extra hours that may be carried over to the next year under §748.937(e)?', options: ['5 hours', '10 hours', '15 hours', '20 hours'], correct: 2, explanation: 'Under §748.937(e), if a person earns more than the minimum annual training hours in a year, the person may carry over a maximum of 15 annual training hours to the next year. A similar 15-hour cap applies to extra pre-service hours used toward annual training (§748.937(b)(3)).' },
      { id: 'e2q11', domain: 'Training', question: 'A GRO allows the use of emergency behavior intervention. At least what percentage of its pre-service emergency behavior intervention training must focus on early identification of potential problem behaviors and less restrictive interventions?', options: ['25 percent', '50 percent', '65 percent', '75 percent'], correct: 3, explanation: 'Under §748.889(a), if you allow emergency behavior intervention, at least 75 percent of the pre-service training must focus on early identification of potential problem behaviors and strategies and techniques of less restrictive interventions (the components in §748.887). The other 25 percent must cover the components in §748.889(c), such as caregiver roles, escape and evasion techniques, safe implementation of restraints and seclusion, and monitoring for physical signs of distress.' },
      { id: 'e2q12', domain: 'Training', question: 'A newly hired child-care administrator at a GRO must complete how many hours of pre-service emergency behavior intervention training, and by when?', options: ['8 hours within 90 days of beginning job duties', '2 hours before beginning job duties', '4 hours within 30 days of beginning job duties', '16 hours before being counted in the ratio'], correct: 0, explanation: 'Under §748.864(a)(2), child-care administrators, professional level service providers, treatment directors, and case managers must complete 8 hours of pre-service emergency behavior intervention training within 90 days of beginning job duties (except an employee exclusively assigned to children with primary medical needs). They also need 2 hours of normalcy training under §748.864(a)(1).' },
      { id: 'e2q13', domain: 'Service Planning & Treatment', question: 'A GRO admits a child for treatment services for an intellectual disability. Under §748.1219(2)(C), the psychological evaluation must be performed by:', options: ['Any licensed health-care professional chosen by the operation', 'A licensed psychologist with relevant intellectual-disability experience', 'The treatment director, regardless of professional license', 'A licensed professional counselor supervised by the administrator'], correct: 1, explanation: 'Under §748.1219(2)(C)(i), the psychological evaluation must be performed by a licensed psychologist who has experience with intellectual disabilities or published scales. It must also use standardized tests to determine intellectual functioning, determine the level of adaptive functioning, and indicate manifestations of an intellectual disability as defined in the DSM-5. It must be completed within 14 months of the date of admission (§748.1219(2)(B)).' },
      { id: 'e2q14', domain: 'Service Planning & Treatment', question: 'For a child who exhibits high-risk behaviors or screens as a high or potential suicide risk, the initial service plan must include plans to minimize the risk of harm and:', options: ['A written waiver of confidentiality from the child\'s parent', 'A court order authorizing one-to-one supervision', 'A transfer summary prepared for the next placement', 'A specific safety contract developed between the child and staff'], correct: 3, explanation: 'Under §748.1337(b)(1)(H), for children who exhibit high-risk behaviors or have a suicide risk screening indicating a high or potential risk, the initial service plan must include (i) plans to minimize the risk of harm to the child or others, such as special instructions for caregivers, sleeping arrangements, or bathroom arrangements, and (ii) a specific safety contract developed between the child and staff that addresses how the child\'s safety needs will be maintained.' },
      { id: 'e2q15', domain: 'Service Planning & Treatment', question: 'A 15-year-old refuses to sign her initial service plan after reviewing it. What does §748.1349(b) require of the operation?', options: ['Document the child\'s refusal to sign', 'Have the child\'s caregiver sign for her', 'Withhold implementation of the plan until she signs', 'Remove the child from the service planning team'], correct: 0, explanation: 'Under §748.1349(a)(1), at a minimum you must give a copy or summary of the initial service plan to a child 14 years of age or older unless there is justification for not providing it. Under §748.1349(b), if you provide the plan to the child, the child must review it and sign it, or you must document the child\'s refusal to sign, and you must document if the child disagrees with the plan.' },
      { id: 'e2q16', domain: 'Child Rights & Discipline', question: 'Under §748.2901(a), a triggered review of emergency behavior intervention is required when the same child is personally restrained:', options: ['Twice within a 24-hour period', 'Four times within a seven-day period', 'Six times within a 14-day period', 'Three times within a 30-day period'], correct: 1, explanation: 'Under §748.2901(a)(2), a triggered review is required when the same child is personally restrained four times within a seven-day period, more than 12 times in a single 30-day period, or more often than a written order or service planning team recommendation allows. Other triggers include emergency medication three times in a 30-day period, and seclusion or mechanical restraint three times in seven days. The review must occur as soon as possible, but no later than 30 days after it is triggered (§748.2903(a)).' },
      { id: 'e2q17', domain: 'Child Rights & Discipline', question: 'Four triggered reviews have occurred for the same child within a 90-day period. Under §748.2909, what must happen?', options: ['The operation must discharge the child within 30 days and notify the child\'s parent and caseworker', 'A licensed clinician, such as a psychiatrist or psychologist, must examine the child and make service plan recommendations', 'The service planning team must stop all emergency behavior intervention for the child and notify Licensing within 24 hours', 'A Licensing representative must approve a revised service plan before the child may remain in care at the operation'], correct: 1, explanation: 'Under §748.2909, if there are four triggered reviews within a 90-day period, a licensed psychiatrist, psychologist, clinical social worker, professional counselor, or marriage and family therapist must examine the child and make service plan recommendations regarding the use of emergency behavior interventions, and you must document those recommendations in the child\'s record.' },
      { id: 'e2q18', domain: 'Child Rights & Discipline', question: 'A written continuation order is obtained to extend a child\'s seclusion beyond the maximum time. Under §748.2807(d), in no event may an order permit seclusion or mechanical restraint to exceed:', options: ['Two hours', 'Three hours', 'Four hours', 'Twelve hours'], correct: 2, explanation: 'Under §748.2807(d) and §748.2805, a continuation order may extend seclusion (ordered by a licensed psychiatrist, psychologist, or physician) or mechanical restraint (ordered by a licensed psychiatrist only), but in no event may the order permit either to exceed four hours. The twelve-hour figure is the point at which continued seclusion triggers a review under §748.2901(a)(4)(A).' },
      { id: 'e2q19', domain: 'Child Rights & Discipline', question: 'An RTC wants to use a mechanical restraint with a psychiatrist\'s written order. Which device may be used under §§748.2701 and 748.2705?', options: ['A commercially available device designed for safe, comfortable restraint of humans', 'A leash or other long tie, if the child is observed continuously', 'Bed sheets or blankets, if the child is checked every 15 minutes', 'A device secured with a key lock, if staff hold the key'], correct: 0, explanation: 'Under §748.2701(a), only commercially available devices specifically designed for the safe and comfortable restraint of humans may be used as mechanical restraints. Under §748.2705, devices with metal cuffs, rubber bands, rope or cord, padlocks or key locks, long ties such as leashes, bed sheets or blankets, and veil beds must not be used. Mechanical restraint may be used only by a residential treatment center (§748.2451(a)(5)).' },
      { id: 'e2q20', domain: 'Health, Safety & Emergency', question: 'How often must a GRO inspect its fire extinguishers, and how often must a company licensed by the State Fire Marshal inspect each one?', options: ['Monthly by the operation; at least annually by the licensed company', 'Weekly by the operation; every two years by the licensed company', 'Quarterly by the operation; every five years by the licensed company', 'Annually by the operation; monthly by the licensed company'], correct: 0, explanation: 'Under §748.3115, you must inspect fire extinguishers monthly to ensure access is not blocked, they are accessible for immediate use, and they are serviced as required. Under §748.3117(a), a company licensed by the State Fire Marshal must inspect each extinguisher at least annually; newly purchased extinguishers do not need inspection during the first 12 months unless the monthly inspection indicates otherwise.' },
      { id: 'e2q21', domain: 'Health, Safety & Emergency', question: 'During an unannounced fire drill, children must be able to safely exit the building to the designated meeting place within:', options: ['One minute', 'Two minutes', 'Three minutes', 'Five minutes'], correct: 2, explanation: 'Under §748.3239(a)(3), during each fire drill the children must be able to safely exit the building to the designated meeting place within three minutes. Drills must be unannounced and held at least once every six months, must set off the fire alarm or a smoke detector, must use alternate exit routes, and must not use elevators; each drill must be documented (§748.3239(a), (d)).' },
      { id: 'e2q22', domain: 'Health, Safety & Emergency', question: 'Under §748.3603(h), the space between the ground and the bottom of the fence enclosing an outdoor swimming pool at your operation must not exceed:', options: ['Two inches', 'Four inches', 'Six inches', 'Eight inches'], correct: 1, explanation: 'Under §748.3603(h), the space between the ground and the bottom of the fence around an outdoor swimming pool must not exceed four inches. Outdoor pools must be enclosed with a six-foot fence or wall that does not obscure the pool from view (§748.3603(d)), and gates must be self-closing and self-latching with hardware at least 60 inches from the ground and must open outward (§748.3603(f), (g)).' },
      { id: 'e2q23', domain: 'Health, Safety & Emergency', question: 'A child experiences a side effect from a medication that is not a serious side effect. Under §748.2233(b), you must document it and report it to the child\'s prescribing health-care professional:', options: ['Immediately, and also to the child\'s parent', 'Within 24 hours', 'Within 48 hours', 'Within 72 hours'], correct: 3, explanation: 'Under §748.2233(b), if a child experiences side effects from any medication you must document the observed and reported side effects, immediately report any serious side effects to the prescribing health-care professional and the child\'s parent, and report any other side effect to the prescribing health-care professional within 72 hours.' },
      { id: 'e2q24', domain: 'Daily Care & Program Operations', question: 'Under §748.1703, a GRO that is not a cottage home must date its daily menus and keep copies for:', options: ['30 days', '60 days', '90 days', '12 months'], correct: 2, explanation: 'Under §748.1703(a)-(c), you must maintain daily menus showing all meals and snacks prepared and served, document food substitutions of comparable food value, and date menus and keep copies for 90 days. Under §748.1703(d), the menu rule does not apply to meals prepared and served in cottage homes.' },
      { id: 'e2q25', domain: 'Daily Care & Program Operations', question: 'You restrict a child\'s ongoing contact with a parent, and the restriction continues for more than 30 days. Under §748.1107(d), the restriction must be re-evaluated monthly by:', options: ['The child-care administrator, with the parent\'s consent', 'The operation\'s governing body or board of directors', 'The child\'s caseworker or placing agency', 'A professional level service provider'], correct: 3, explanation: 'Under §748.1107(d), restrictions imposed by the operation that continue for more than 30 days must be re-evaluated monthly by a professional level service provider, who must also explain the reasons for the continued restrictions to the child and the child\'s parents and document the reasons in the child\'s record. The initial restriction requires an explanation to the child and parent and documentation (§748.1107(c)). Restrictions imposed by a court or parent are not subject to these rules.' },
    ],
  },
  {
    id: 'exam-3',
    number: 3,
    title: 'Practice Exam 3',
    description: 'An applied set of 25 scenario-based questions in which you act as the GRO administrator and choose the best action under Texas 26 TAC Chapter 748 across reporting, personnel, training, service planning, child rights, safety, and daily care.',
    questions: [
      { id: 'e3q1', domain: 'Regulatory Framework', question: 'You are the GRO administrator. A kitchen fire makes one cottage unsafe for the children for several days, and you must move them to another building on your campus. What is your best action under §748.303(e)(1)?', options: ['Report to Licensing within two hours and to law enforcement immediately after the fire', 'Wait until the cottage is repaired, then include the fire in your next quarterly report', 'Report to Licensing and parents as soon as possible, but within 24 hours after the incident', 'Notify only the fire department, and document the incident in each affected child\'s record'], correct: 2, explanation: 'Under §748.303(e)(1), an incident that renders all or part of the GRO unsafe or unsanitary for a child, such as a fire or a flood, must be reported to Licensing and to parents as soon as possible, but no later than 24 hours after the incident. The report is made to the Texas Abuse and Neglect Hotline (§748.309) and documented in writing under §748.311.' },
      { id: 'e3q2', domain: 'Regulatory Framework', question: 'You are the GRO administrator. A caregiver is arrested for an offense of the type described in §745.661. What is your best action under §748.303(e)(7)?', options: ['Report to Licensing as soon as you become aware; parents are not notified under this item', 'Wait for a conviction before reporting anything to Licensing about the arrest', 'Report to Licensing within 72 hours and notify the parents of every child in care', 'Treat it as an internal personnel matter unless the caregiver was on duty at the time'], correct: 0, explanation: 'Under §748.303(e)(7), an arrest, indictment, accepted official complaint, or executed arrest warrant alleging an employee, professional level service provider, contract staff member, volunteer, or other adult committed a crime described in §745.661 must be reported to Licensing as soon as the GRO becomes aware of the situation. The table does not require notice to parents for this item, and no conviction is needed before reporting.' },
      { id: 'e3q3', domain: 'Regulatory Framework', question: 'You are the GRO administrator. You could not renew your liability insurance because no underwriter would issue a policy, and a new child is about to be admitted. What is your best action?', options: ['Admit the child now and notify the parent in writing within 14 days after admission', 'Skip all notification, because liability insurance is optional for a general residential operation', 'Notify Licensing within 24 hours and admit the child only after Licensing gives approval', 'Notify Licensing in writing by the permit anniversary date and the new child\'s parent before admission'], correct: 3, explanation: 'Under §748.159(a)(2), being unable to locate an underwriter willing to issue a policy is an acceptable reason not to carry the $300,000 coverage required by §748.158, but under §748.159(b) you must send Licensing written notice with the reason by the permit anniversary date. Under §748.160(a), you must notify the parent of each child in writing that you do not carry liability insurance before you admit the child. Parents of children already in care must be notified within 14 days after you stop carrying the insurance (§748.160(b)).' },
      { id: 'e3q4', domain: 'Regulatory Framework', question: 'You are the GRO administrator. A child has lived at your operation for three years, and the records for the child\'s first two years of care are archived off-site. A Licensing inspector asks to review them. What must you do under §§748.391 and 748.401?', options: ['Make them available within 48 hours; records that are not active may be archived electronically or kept anywhere safe from damage or destruction', 'Produce them immediately, because all child records must be available for immediate review', 'Make them available within 30 days, since archived records are exempt from the 48-hour rule', 'Nothing; archived records do not have to be shown to Licensing'], correct: 1, explanation: 'Under §748.391, an active child record is the record for the most recent 12 months of service, and active records must be available for Licensing\'s immediate review and reproduction (§748.399(a)). Under §748.401, records that are not active must be available for review within 48 hours; otherwise they may be archived electronically or kept anywhere, in any manner, as long as they are safe from damage or destruction.' },
      { id: 'e3q5', domain: 'Administrator & Personnel', question: 'You are the GRO administrator, about to hire a caregiver. The applicant\'s previous employer has not responded to your first call. What is your best action under §748.751?', options: ['Make at least two attempts to reach the employer and document them in the personnel file', 'Hire the applicant without further effort, since an application was already submitted', 'Ask the applicant to sign a statement verifying his own employment history', 'Try once more and treat verification as waived if the employer does not answer'], correct: 0, explanation: 'Under §748.751(a), before hiring an applicant the operation must conduct employment verification, to the extent possible, by contacting the previous employers listed in the application materials. Under §748.751(b), the operation must document the applicant\'s employment history in the personnel file along with two or more attempts to contact a previous employer, and if an employer is determined to be permanently unreachable, the reason for that determination.' },
      { id: 'e3q6', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. Cottage A has 8 children ages 7 to 16, none receiving treatment services. Cottage B has 5 children ages 10 to 15, one of whom receives treatment services. For a movie night, both groups will be combined during waking hours. How many caregivers are required for the combined group?', options: ['One', 'Two', 'Three', 'Four'], correct: 2, explanation: 'Under §748.1003(b)(2), the child/caregiver ratio must be re-calculated any time groups intermingle. The combined group has 13 children (none under five, so none count double), and at least one child requires treatment services, so the waking-hours ratio is 1:5 under §748.1003(a). Thirteen children divided by five requires three caregivers, even though the two groups needed only one caregiver each when separate.' },
      { id: 'e3q7', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. A caregiver says she suspects another employee abused a child and asks you to call the Hotline for her because you are the administrator. What is the best response under §748.105(8)?', options: ['Agree and make the report to the Hotline on her behalf as the administrator', 'Tell her to report directly to the Hotline herself; she cannot delegate it or need approval', 'Have her report it to her supervisor, who will decide whether the Hotline is called', 'Ask her to wait until you have finished an internal investigation of the employee'], correct: 1, explanation: 'Under §748.105(8), an employee who suspects abuse, neglect, or exploitation must report the suspicion directly to the Texas Abuse and Neglect Hotline, as directed by Texas Family Code §261.101(b). The employee may not delegate the responsibility to make the report, and the operation may not require the employee to seek approval to file a report or to notify the operation that a report was made. Employees must also report to the designated employee or administrator (§748.507(2)).' },
      { id: 'e3q8', domain: 'Training', question: 'You are the GRO administrator. A newly hired caregiver has no CPR certification yet. The night shift needs a caregiver counted in ratio, and she would be the only caregiver on duty. What should you do under §748.911(c)?', options: ['Assign her, because she has 90 days to complete CPR certification', 'Assign her if she holds a current first-aid certificate', 'Assign her if the administrator will be on call that night', 'Do not assign her alone until she is CPR certified'], correct: 3, explanation: 'Under §748.911(c)(2), each caregiver must be certified in CPR and able to respond to emergencies prior to being the only caregiver counted in the child/caregiver ratio. The 90-day timeframe in §748.911(c)(1) applies to first-aid certification, which must be completed within 90 days of employment.' },
      { id: 'e3q9', domain: 'Training', question: 'You are the GRO administrator. A caregiver earns a passing grade in a three-credit-hour college course on child development. How many annual training hours may you credit under §748.937(a)(7)?', options: ['3 hours', '15 hours', '50 clock hours', 'None, because college courses cannot count toward annual training'], correct: 2, explanation: 'Under §748.937(a)(7), completed college courses with a passing grade may count toward annual training, with three college credit hours equivalent to 50 clock hours of required training. College courses cannot substitute for required CPR or first-aid certification or for required annual training on emergency behavior intervention or psychotropic medication. A college transcript is acceptable documentation (§748.949(a)).' },
      { id: 'e3q10', domain: 'Training', question: 'You are the GRO administrator. You plan to meet the annual psychotropic medication training requirement for caregivers who administer these medications by assigning a self-paced online module only. What is the best course of action under §748.941?', options: ['Proceed, because self-instructional training satisfies every annual training requirement', 'Add instructor-led training by a health-care professional or pharmacist who assesses participants', 'Substitute a college child-development course for the medication training', 'Proceed if you personally sign off on each caregiver\'s completion of the module'], correct: 1, explanation: 'Under §748.941(b), training on administering psychotropic medication must be instructor-led, and under §748.941(d) a health-care professional or pharmacist must lead it and assess each participant afterward. College courses cannot substitute (§748.937(a)(7)). The technical assistance to §748.945 notes that the DFPS online psychotropic medication module can satisfy the requirement only if caregivers also receive instructor-led training on the operation\'s medication policies and on who may consent.' },
      { id: 'e3q11', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator completing a non-emergency admission assessment. A child\'s previous school records still have not arrived despite your requests. What is your best action under §748.1221?', options: ['Make reasonable efforts and document why the records are unavailable', 'Delay the admission indefinitely until every record has arrived from the school', 'Leave that section of the assessment blank and note it on the next review', 'Ask the parent to sign a waiver of the admission assessment requirement'], correct: 0, explanation: 'Under §748.1221(a) and (c), you must make reasonable efforts to obtain all required information, and in the admission assessment you must document why a particular piece of information is unavailable, including the efforts made. The technical assistance explains Licensing expects documentation of at least three reasonably spaced attempts, such as one call a week for three weeks.' },
      { id: 'e3q12', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. You plan to place a child receiving treatment services for an emotional disorder in a cottage where the other children receive child-care services only. What must happen first under §748.1201(a)?', options: ['The Licensing Representative must approve the placement in writing beforehand', 'The child\'s parent must agree to the cottage assignment in writing beforehand', 'The governing body must amend the operation\'s permit before the placement', 'A professional level service provider must evaluate the living quarters'], correct: 3, explanation: 'Under §748.1201(a), children receiving different types of service may share living quarters if a professional level service provider evaluates the living quarters for each child placed there and ensures, among other things, that there is no conflict of care, the placement will not adversely impact the other children, the number of children is appropriate, caregivers can supervise all children, and the operation can meet everyone\'s needs. If a child\'s needs change, the provider must re-evaluate (§748.1201(b)).' },
      { id: 'e3q13', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. You move a child to another cottage because a bed opened up, not because the child\'s needs changed. Must you review the child\'s service plan under §748.1383?', options: ['Yes, a review is required whenever a child\'s living arrangement changes in any way', 'No, if the service planning team approves skipping the review and you document it', 'No, but only if the child\'s parent consents in writing to skipping the review', 'Yes, and a new admission assessment must be completed within 40 days'], correct: 1, explanation: 'Under §748.1383(a), you must review the service plan whenever the child\'s placement changes because of a change in the child\'s needs. Under §748.1383(b), if the placement changes for another reason, the child\'s service planning team must approve the decision not to review the plan and you must document that decision.' },
      { id: 'e3q14', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. At 4 p.m. a man the caregiver has never met says the parent sent him to pick up a child. What is the best action under §748.1481?', options: ['Release the child, because the man knows the child\'s name and the parent\'s name and says it is urgent', 'Release the child only if the child says she recognizes the man, and then notify the parent later', 'Verify his authorization under your policy, log his identity, and retain it until the child returns', 'Refuse, and report an attempted abduction to law enforcement and to Licensing within one hour'], correct: 2, explanation: 'Under §748.1481(a), except in an emergency you may release a child only to the child\'s parent, a person designated by the parent, law enforcement, or a person authorized by law. Under §748.1481(b), employees must follow your policies for releasing a child, verifying the identity of a person authorized to pick up a child whom the caregiver does not know, recording the person\'s identity in a log or other designated location, and retaining the identifying information until the child returns.' },
      { id: 'e3q15', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A caregiver has reasonable suspicion that a child hid a prohibited item under her clothing, and a search requiring removal of clothing (other than outer clothing) is needed. Which approach is correct under §748.1113?', options: ['A same-gender caregiver does it, a second caregiver witnesses, and other children cannot see', 'Any available caregiver does it, and the administrator is told about it afterward', 'Two caregivers of any gender do it in the common room so the search is transparent', 'The search is prohibited; only a law enforcement officer may search a child\'s clothing'], correct: 0, explanation: 'Under §748.1113(b), a search is allowed on reasonable suspicion of a prohibited or dangerous item, suicidal or violent threats, or theft. Under §748.1113(d)-(f), only a caregiver of the same gender may conduct a search involving removal of clothing other than outer clothing, a second caregiver must witness it, and the caregiver must ensure other children do not witness it. The search must be documented under §748.1117, and body cavity searches (except of a child\'s mouth) are prohibited by §748.1115.' },
      { id: 'e3q16', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A caregiver wants to restrict a child\'s off-campus activities for three weeks as a behavior management tool. What must happen first under §748.2309?', options: ['Nothing is needed; caregivers may restrict a child\'s activities for as long as they choose', 'A court order must authorize any restriction lasting longer than a week', 'The parent must approve the restriction in writing and send a copy to Licensing within 24 hours', 'Prior approval by the treatment director, service planning team, or professional level service provider'], correct: 3, explanation: 'Under §748.2309(a)-(b), within limits a caregiver may restrict a child\'s activities as a behavior management tool, but a longer restriction (more than fourteen days) must have prior approval by the treatment director, service planning team, or professional level service provider. Under §748.2309(d)-(e), you must inform the child and parent of the restriction and document all approvals, the justification, and the notification in the child\'s record.' },
      { id: 'e3q17', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. You hired a caregiver in 2021 and want to designate her to make decisions about children\'s participation in childhood activities, but she has had no normalcy training. What should you do under §748.709?', options: ['Designate her now, since she works at the location where the children live and knows them', 'Designate her after 90 days of employment, whether or not she has had normalcy training', 'Designate her only after the two-hour pre-service or the annual normalcy training', 'Designate her only after each child\'s parents approve her designation in writing'], correct: 2, explanation: 'Under §748.709(a), a caregiver hired after August 31, 2016 may not be a designated person who decides on a child\'s participation in childhood activities until the caregiver completes either a two-hour pre-service training on normalcy or the annual training specific to normalcy. Under §748.709(b), the designated person must work at the location where the child resides and be knowledgeable about the child\'s current needs and history, and the name must be documented on the face sheet of the child\'s record (§748.709(c)).' },
      { id: 'e3q18', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A caregiver wants to open a child\'s incoming mail to check for contraband, though no one has determined that the child\'s mail should be restricted. What is the best response under §748.1111(a)?', options: ['Yes, caregivers may screen all of a child\'s mail for safety and contraband reasons', 'No, unless the team, treatment director, a professional, or the parent determines it is necessary', 'Yes, as long as two caregivers are present when the mail is opened and read', 'Yes, but only for children under 13, and only with a second caregiver witnessing'], correct: 1, explanation: 'Under §748.1111(a), except as determined by the child\'s service planning team, treatment director, professional level service provider, or parent, you may not open or read the child\'s incoming or outgoing mail, including electronic mail, unless necessary to assist the child with reading or writing, or listen to or screen the child\'s telephone calls unless the child needs help using the phone. Any restrictions must be documented and explained to the child and parent (§748.1111(b), (c)), and restrictions continuing more than 30 days must be re-evaluated monthly by a professional level service provider (§748.1111(d)).' },
      { id: 'e3q19', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A caregiver realizes she skipped a child\'s scheduled dose of a prescribed medication earlier today. What does §748.2203 require?', options: ['Call a health-care professional immediately and document only if the child shows symptoms', 'Give a double dose at the next scheduled time to make up for the missed one', 'Document nothing unless the child shows symptoms later that day', 'Document the error within 24 hours; an immediate call is not required for a skipped dose'], correct: 3, explanation: 'Under §748.2203(a), for an error with a prescribed medication you must contact a health-care professional immediately and follow the recommendations, unless the error is a dose given at the wrong time or a skipped or missed dose (§748.2201(4), (5)). Under §748.2203(c), for all medication errors you must document within 24 hours the time and date of the error, the error itself, and, if applicable, the call to the health-care professional and that person\'s recommendations.' },
      { id: 'e3q20', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. Your GRO takes eight children, ages 9 to 16, to swim at a lake on an operation-sponsored outing. Which requirement applies under §748.3751(b)?', options: ['One adult who is able to swim is sufficient for a group this size', 'A certified lifeguard must also be on duty, since more than six children swim', 'A lifeguard is required only for the children who are under 12 years old', 'No lifeguard is needed if every child passes a swim test before entering'], correct: 1, explanation: 'Under §748.3751(b), for a swimming activity in water two feet deep or more away from the operation, if six or fewer children participate at least one adult counted in the swimming ratio must be able to swim or be trained in water rescue, but if more than six children participate a certified lifeguard must also be on duty. Children under 12 or unable to swim must wear a Coast Guard approved life jacket in lakes and similar waters (§748.3757(d)), and more than six children also requires life-saving equipment such as a throw bag with a 50-foot buoyant rope (§748.3765(b)(3)).' },
      { id: 'e3q21', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator updating your emergency evacuation and relocation diagram. One of the two exit routes passes through the kitchen. What does §748.3233(b)(4)(C) require?', options: ['Written approval signed and dated by the fire inspector, kept at the operation', 'Nothing; any two exit routes are acceptable if both lead outside', 'A signed and dated note on the diagram by the administrator and the cook', 'Replacing the route only if a drill takes longer than five minutes'], correct: 0, explanation: 'Under §748.3233(b)(4)(C), exit routes must not go through a kitchen or other hazardous area unless specifically approved in writing by the state or local fire inspector; the approval must be signed and dated and maintained at the operation for Licensing\'s review. The diagram must also show a floor plan, the outside meeting place, the inside shelter location for threatening weather, and at least two unblocked exit routes in distant parts of the building (§748.3233(b)). It must be posted in all buildings (§748.3235).' },
      { id: 'e3q22', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A child receiving treatment services asks to join the operation\'s archery program. What does §748.3931 require?', options: ['Allow it, but only with direct supervision by a knowledgeable adult', 'Allow it if the child\'s parent signs a waiver and the program is approved', 'Deny it; children in treatment services may not use projectiles such as arrows', 'Allow it if the bows and the arrows are kept in separate locked storage'], correct: 2, explanation: 'Under §748.3931(a)(2), a child receiving treatment services or emergency care services is not permitted to use weapons, firearms, explosive materials, or projectiles (the rule gives darts or arrows as examples). For a child receiving only child-care services, you must determine whether use is appropriate, and the child must be directly supervised by a knowledgeable adult (§748.3931(a)(4), (5)). Handguns are never permitted (§748.3931(a)(1)).' },
      { id: 'e3q23', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator. A school-age child has skipped several meals over the past two weeks. Staff offered meals each time and did not force him. What else does §748.1699 require?', options: ['Discuss the recurring eating problem with the child\'s parent', 'Require the child to finish a meal before leaving the table', 'Serve extra snacks in place of the skipped meals', 'Report the child to Licensing as a neglect incident'], correct: 0, explanation: 'Under §748.1699(a), you must offer meals but may not force a child to eat, and you need not offer other food to a child who refuses a meal. Under §748.1699(b), you must discuss recurring eating problems with the child\'s parent. An appropriate nutritional substitute is required only when a meal is not appropriate for the child\'s individual needs, such as food allergies or religious reasons (§748.1699(c)).' },
      { id: 'e3q24', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator. A physician recommends a diabetic diet for a child. What must you have before serving a therapeutic or special diet under §748.1701?', options: ['Verbal approval from the physician, documented in the cook\'s notes for the kitchen', 'The parent\'s written permission, filed in the child\'s record along with the diet', 'A letter of approval from the Texas Department of State Health Services', 'Written approval from a licensed physician or a registered or licensed dietitian'], correct: 3, explanation: 'Under §748.1701(a), to serve a therapeutic or special diet you must have written approval in the child\'s record from a licensed physician or a registered or licensed dietitian. Under §748.1701(b), you must give information about the diet to all employees who prepare and serve food and to the child\'s caregivers, and under §748.1701(c) you must make dietary alternatives available to a child with special health needs.' },
      { id: 'e3q25', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator. A 15-year-old in your transitional living program says she is ready to live without caregiver supervision. What is the best response under §748.1021?', options: ['Approve it, because the child has shown maturity in her daily routines', 'Approve it if her parent agrees in writing and a caregiver checks in daily', 'Do not approve; she must be 16 or older, and a written evaluation is also required', 'Approve it for weekends only, with a nightly phone check'], correct: 2, explanation: 'Under §748.1021(a), a child in a transitional living program may be without supervision only if the child is 16 years old or older. Under §748.1021(b)-(d), you must also evaluate the child, with a written plan for the periods the child may be unsupervised, a written plan for behavioral problems, and a way for the child to contact caregivers; the child\'s service planning team must approve the evaluation, and it must be documented and reviewed at service planning meetings.' },
    ],
  },
];
